draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // uncertain path
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t) * 20, H/2 + 100);
  ctx.stroke();

  // hopeful arrow
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 20, H/2 + 100);
  ctx.lineTo(W/2 + Math.sin(t) * 20 + 20, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 20 + 10, H/2 + 120);
  ctx.lineTo(W/2 + Math.sin(t) * 20 + 30, H/2 + 110);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 20 + 10, H/2 + 120);
  ctx.lineTo(W/2 + Math.sin(t) * 20 + 30, H/2 + 130);
  ctx.stroke();

  ctx.restore();
}
